[{"order":1,"type":"heading","text":"Concurrency Patterns in Go: Worker Pool, Fan-out, and Fan-in"},{"order":2,"type":"paragraph","text":"Go's concurrency model, built upon goroutines and channels, enables developers to write highly scalable concurrent applications. When dealing with high-throughput systems or parallelizable task execution, specific design patterns emerge as industry standards. This tutorial explores the Worker Pool, Fan-out, and Fan-in patterns."},{"order":3,"type":"subheading","text":"1. Understanding the Worker Pool Pattern"},{"order":4,"type":"paragraph","text":"A Worker Pool restricts the number of concurrently running goroutines to prevent resource exhaustion (such as running out of memory or file descriptors). Instead of spawning a new goroutine for every single task, a fixed number of worker goroutines read from a shared task channel."},{"order":5,"type":"code","text":"package main

import (
	"fmt"
	"time"
)

func worker(id int, jobs <-chan int, results chan<- int) {
	for j := range jobs {
		fmt.Printf("Worker %d started job %d\n", id, j)
		time.Sleep(time.Second)
		fmt.Printf("Worker %d finished job %d\n", id, j)
		results <- j * 2
	}
}

func main() {
	const numJobs = 5
	jobs := make(chan int, numJobs)
	results := make(chan int, numJobs)

	// Start 3 workers
	for w := 1; w <= 3; w++ {
		go worker(w, jobs, results)
	}

	// Send jobs and close the channel
	for j := 1; j <= numJobs; j++ {
		jobs <- j
	}
	close(jobs)

	// Collect results
	for a := 1; a <= numJobs; a++ {
		<-results
	}
}"},{"order":6,"type":"subheading","text":"2. The Fan-out Pattern"},{"order":7,"type":"paragraph","text":"Fan-out involves multiple goroutines reading from the same channel until that channel is closed. This pattern allows you to distribute tasks across multiple worker routines concurrently, effectively spreading the computational load."},{"order":8,"type":"bullet_point","text":"Distributes work among multiple concurrent workers."},{"order":9,"type":"bullet_point","text":"Automatically handles load balancing since workers pull from a shared queue dynamically."},{"order":10,"type":"subheading","text":"3. The Fan-in Pattern"},{"order":11,"type":"paragraph","text":"Fan-in is the process of combining multiple distinct channels into a single unified channel. A separate goroutine reads from all input channels and passes the values through to a single output channel, allowing a downstream consumer to process results uniformly."},{"order":12,"type":"code","text":"package main

import (
	"fmt"
	"sync"
)

func producer(val int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		out <- val
	}()
	return out
}

func fanIn(channels ...<-chan int) <-chan int {
	var wg sync.WaitGroup
	out := make(chan int)

	output := func(c <-chan int) {
		defer wg.Done()
		for n := range c {
			out <- n
		}
	}

	wg.Add(len(channels))
	for _, c := range channels {
		go output(c)
	}

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

func main() {
	chan1 := producer(10)
	chan2 := producer(20)

	combined := fanIn(chan1, chan2)

	for v := range combined {
		fmt.Println(v)
	}
}"},{"order":13,"type":"subheading","text":"Summary"},{"order":14,"type":"paragraph","text":"By combining Worker Pools, Fan-out, and Fan-in patterns, Go developers can architect robust, scalable pipelines. Fan-out dispatches the work efficiently, Worker Pools limit resource saturation, and Fan-in consolidates outputs for clean downstream handling."}]
